program='''from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == bg and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == bg and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in grid]
    seen=set(outside)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen: continue
            comp=[]; q=deque([(r,c)]); seen.add((r,c))
            while q:
                p=q.popleft(); comp.append(p)
                pr,pc=p
                for nr,nc in ((pr-1,pc),(pr+1,pc),(pr,pc-1),(pr,pc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            color=7 if len(comp)%2 else 2
            for rr,cc in comp: out[rr][cc]=color
    return out
'''
